#include <bits/stdc++.h>
using namespace std;
template<class T> vector<T> readbin(string name){ifstream f(name,ios::binary|ios::ate);size_t n=f.tellg()/sizeof(T);vector<T> v(n);f.seekg(0);f.read((char*)v.data(),n*sizeof(T));return v;}
int main(){int nr,nc;long long nz;ifstream("dimensions.txt")>>nr>>nc>>nz;auto cp=readbin<int64_t>("col_ptr.bin");auto ci=readbin<int32_t>("col_idx.bin");auto cd=readbin<int8_t>("col_dat.bin");auto rp=readbin<int64_t>("row_ptr.bin");auto ri=readbin<int32_t>("row_idx.bin");auto rd=readbin<int8_t>("row_dat.bin");auto rhs=readbin<int32_t>("rhs.bin");vector<int> lo(nr),hi(nr),val(nc,-1);vector<char> inq(nr,0);deque<int> qu;auto trigger=[&](int i){if(!inq[i]&&(rhs[i]<=lo[i]||rhs[i]>=hi[i])){inq[i]=1;qu.push_back(i);}};for(int i=0;i<nr;i++){for(auto k=rp[i];k<rp[i+1];k++){if(rd[k]<0)lo[i]--;else hi[i]++;}trigger(i);}ofstream out("twolevel154_steps.txt");int assigned=0,ones=0,conflict=-1;while(!qu.empty()){int row=qu.front();qu.pop_front();inq[row]=0;if(rhs[row]<lo[row]||rhs[row]>hi[row]){conflict=row;break;}if(rhs[row]!=lo[row]&&rhs[row]!=hi[row])continue;bool low=rhs[row]==lo[row];for(auto k=rp[row];k<rp[row+1];k++){int col=ri[k];if(val[col]>=0)continue;int v=low?(rd[k]<0):(rd[k]>0);val[col]=v;assigned++;ones+=v;out<<col<<" "<<v<<" "<<row<<"\n";for(auto kk=cp[col];kk<cp[col+1];kk++){int rr=ci[kk],sg=cd[kk];rhs[rr]-=sg*v;if(sg<0)lo[rr]++;else hi[rr]--;trigger(rr);}}}out.close();ofstream vout("twolevel154_values.bin",ios::binary);vout.write((char*)val.data(),val.size()*sizeof(int));ofstream report("twolevel154_propagation.json");report<<"{\"assigned\":"<<assigned<<",\"ones\":"<<ones<<",\"remaining\":"<<nc-assigned<<",\"conflict_row\":"<<conflict;
if(conflict>=0)report<<",\"rhs\":"<<rhs[conflict]<<",\"lo\":"<<lo[conflict]<<",\"hi\":"<<hi[conflict];report<<"}\n";report.close();cout<<assigned<<" assigned, "<<ones<<" ones, "<<nc-assigned<<" remaining, conflict "<<conflict<<endl;}
